import { readFileSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { LEVEL_ORDER } from "./levels.ts";

// The table is built from the level list, so a new level cannot be missing from it.
export function commandsTable(): string {
  const rows = LEVEL_ORDER.map(
    (l) =>
      `| ${l} | \`make levels LEVEL=${l}\` | \`make prove LEVEL=${l}\` | \`make exercise LEVEL=${l} TRACK=a\` |`,
  );
  return [
    "# Commands by level",
    "",
    "Generated by `npx tsx scripts/commands.ts`. Do not edit by hand.",
    "",
    "| Level | Get a finished copy | Prove it | Check the exercise |",
    "|---|---|---|---|",
    ...rows,
    "",
  ].join("\n");
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  writeFileSync("docs/commands-by-level.md", commandsTable());
}

export const committed = () => readFileSync("docs/commands-by-level.md", "utf8");
